// DataCatalog, 45 entities
export const JSONLD_KNOWLEDGE_SYSTEM_HUB = "{\"@context\":\"https://schema.org\",\"@type\":\"DataCatalog\",\"name\":\"ELIMFILTERS Knowledge Vault\",\"description\":\"Machine-readable industrial filtration knowledge graph covering contamination modes, technologies, standards, and product families.\",\"url\":\"https://elimfilters.com/knowledge-system\",\"publisher\":{\"@type\":\"Organization\",\"name\":\"ELIMFILTERS\",\"url\":\"https://elimfilters.com\"},\"dataset\":[{\"@type\":\"Dataset\",\"name\":\"HYDROCORE™\",\"description\":\"HYDROCORE is a multi-stage coalescing fuel filtration technology that removes free water (>99% efficiency) and emulsified water (>95% efficiency) from diesel fuel using a coalescing-then-hydrophobic-barrier element architecture, preventing water-induced injector erosion and microbial fuel contamination in common-rail diesel engines operating at 1,800–2,500 bar injection pressure.\",\"url\":\"https://elimfilters.com/knowledge-system/technologies/hydrocore\",\"version\":\"1.0\"},{\"@type\":\"Dataset\",\"name\":\"INTEKCORE — Zero-Bypass Radial Seal Housing\",\"description\":\"INTEKCORE is a zero-bypass radial seal air filter housing technology that eliminates installation-induced and vibration-induced bypass in diesel engine intake systems through a self-centering radial interference seal between filter element end-cap and housing bore, independent of axial clamping force.\",\"url\":\"https://elimfilters.com/knowledge-system/technologies/intekcore\",\"version\":\"1.0\"},{\"@type\":\"Dataset\",\"name\":\"MACROCORE™\",\"description\":\"Progressive Density Gradient (PDG) multi-layer air intake filtration system achieving 99.9%–99.98% particle interception efficiency under ISO 5011 certification with a 62 PSI anti-collapse structural rating for heavy-duty combustion engines.\",\"url\":\"https://elimfilters.com/technologies/macrocore\",\"version\":\"1.0\"},{\"@type\":\"Dataset\",\"name\":\"MICROKAPPA™\",\"description\":\"MICROKAPPA is a cabin air filtration technology certified to ISO 11155-1 (particulate) and ISO 11155-2 (gaseous contaminants) that removes >95% of PM10 and >85% of PM2.5 particulate contamination from operator cab air supply in industrial equipment, protecting occupants from respirable crystalline silica, agricultural dust, diesel particulate matter, and chemical vapors.\",\"url\":\"https://elimfilters.com/knowledge-system/technologies/microkappa\",\"version\":\"1.0\"},{\"@type\":\"Dataset\",\"name\":\"NANOFORCE™\",\"description\":\"NANOFORCE is a sub-micron lube oil and hydraulic fluid filtration technology deployed in kidney-loop or bypass circuit configurations, achieving ISO 4406 cleanliness codes of 15/13/10 or better through Beta(x[c]) ≥ 1000 efficiency at 5 µm absolute — targeting the 1–5 µm particle size range that conventional full-flow filters pass and that is the primary abrasive threat at precision bearing clearances.\",\"url\":\"https://elimfilters.com/knowledge-system/technologies/nanoforce\",\"version\":\"1.0\"},{\"@type\":\"Dataset\",\"name\":\"SYNTEPORE — All-Synthetic Intake Media\",\"description\":\"SYNTEPORE is an all-synthetic air intake filter media that maintains rated particle capture efficiency (ISO 5011, SAE J1539) across the full humidity operating range — from 0% to 100% relative humidity — by eliminating moisture absorption, structural degradation, and efficiency loss inherent in cellulose-based intake media.\",\"url\":\"https://elimfilters.com/knowledge-system/technologies/syntepore\",\"version\":\"1.0\"},{\"@type\":\"Dataset\",\"name\":\"SYNTRAX — Full-Flow Lube Protection\",\"description\":\"SYNTRAX is a full-flow lube oil filtration technology that maintains ISO 4406 cleanliness at 16/14/11 in engine and hydraulic lube circuits by combining high-efficiency particulate capture (ISO 16889 Beta ratio rated) with soot agglomerate removal above 2% by weight concentration, preventing both abrasive particle wear and soot-induced oil degradation.\",\"url\":\"https://elimfilters.com/knowledge-system/technologies/syntrax\",\"version\":\"1.0\"},{\"@type\":\"Dataset\",\"name\":\"Agriculture\",\"description\":\"Agriculture is a HIGH contamination exposure industrial category for diesel-powered equipment, characterized by airborne dust concentrations above 100 mg/m³ during harvest operations, outdoor fuel storage water contamination risks, and seasonal intensive-operation periods that accumulate high contamination loads without daily maintenance oversight.\",\"url\":\"https://elimfilters.com/knowledge-system/industries/agriculture\",\"version\":\"1.0\"},{\"@type\":\"Dataset\",\"name\":\"Automotive\",\"description\":\"Automotive is a MODERATE contamination exposure industrial category for passenger car and light commercial vehicle diesel powertrain applications, with contamination risk concentrated in lube oil particle accumulation in high-speed TDI/CRDI engine bearing and turbocharger circuits (highway ambient particle ingestion: 5–15 mg/m³) and fuel water contamination affecting common-rail injection systems operating at 1,600–2,000 bar with 1–3 µm injector clearances.\",\"url\":\"https://elimfilters.com/knowledge-system/industries/automotive\",\"version\":\"1.0\"},{\"@type\":\"Dataset\",\"name\":\"Bus & Coach\",\"description\":\"Bus & Coach is a MODERATE contamination exposure industrial category for public and passenger transport vehicle operations, with contamination risk driven by high-cycle urban stop-start engine soot loading, depot fuel tank condensation water accumulation, and passenger cabin PM2.5 exposure in traffic-congested urban corridors where ambient diesel particulate concentrations regularly exceed WHO 24-hour guidelines of 15 µg/m³.\",\"url\":\"https://elimfilters.com/knowledge-system/industries/bus-coach\",\"version\":\"1.0\"},{\"@type\":\"Dataset\",\"name\":\"Construction\",\"description\":\"Construction is a HIGH contamination exposure industrial category for heavy equipment, with concurrent silica-bearing airborne dust, hydraulic system wear particle generation, diesel fuel water contamination, and operator cabin air quality hazards all simultaneously present in excavator, loader, bulldozer, and compactor operations.\",\"url\":\"https://elimfilters.com/knowledge-system/industries/construction\",\"version\":\"1.0\"},{\"@type\":\"Dataset\",\"name\":\"Marine\",\"description\":\"Marine is a HIGH contamination exposure industrial category for diesel-powered vessels and offshore equipment, characterised by near-100% ambient relative humidity accelerating fuel tank condensation and lube oil emulsification, salt-air intake environments degrading conventional filter media, and the operational consequence that engine failure at sea is catastrophic — no recovery option and IMO/classification society regulatory compliance requirements for fuel and hydraulic filtration.\",\"url\":\"https://elimfilters.com/knowledge-system/industries/marine\",\"version\":\"1.0\"},{\"@type\":\"Dataset\",\"name\":\"Mining\",\"description\":\"Mining operations present EXTREME contamination exposure — silica and hardrock particulate concentrations 50× above ISO 5011 test standards — requiring multi-system filtration protection across air intake, hydraulic, lube oil, and fuel domains for 24/7 asset reliability.\",\"url\":\"https://elimfilters.com/industries/mining\",\"version\":\"1.0\"},{\"@type\":\"Dataset\",\"name\":\"Oil & Gas\",\"description\":\"Oil & Gas is an EXTREME contamination exposure industrial category for diesel and gas-powered drilling, compression, and pipeline equipment operating in remote locations where equipment failure costs $15,000–$50,000/day in downtime and compressor bearing failure costs $200,000+ per event — driven by desert silica dust in air intake, gas condensate in compressor lube oil, H₂S-accelerated oil acidification, and extended service intervals enforced by remote logistics constraints.\",\"url\":\"https://elimfilters.com/knowledge-system/industries/oil-gas\",\"version\":\"1.0\"},{\"@type\":\"Dataset\",\"name\":\"Power Generation\",\"description\":\"Power generation is a HIGH contamination exposure industrial category for stationary diesel generators, gas turbines, and CHP plants where contamination-driven failure during emergency activation has outage costs of $100,000–$1,000,000+ per event — driven by standby fuel water accumulation causing emergency startup failure, turbine compressor blade erosion from inlet air particles, and lube circuit contamination reducing generator MTBF from 20,000+ hours to 6,000–8,000 hours.\",\"url\":\"https://elimfilters.com/knowledge-system/industries/power-generation\",\"version\":\"1.0\"},{\"@type\":\"Dataset\",\"name\":\"Railway\",\"description\":\"Railway is a HIGH contamination exposure industrial category for diesel locomotive and maintenance-of-way equipment, characterised by extended high-load duty cycles generating elevated lube oil soot, ballast silica dust exposure creating operator respiratory risk, and overhaul economics where locomotive engine failure costs $500,000–$2,000,000 per event making contamination control the primary reliability investment.\",\"url\":\"https://elimfilters.com/knowledge-system/industries/railway\",\"version\":\"1.0\"},{\"@type\":\"Dataset\",\"name\":\"Trucks & Fleets\",\"description\":\"Trucks & Fleets is a MODERATE contamination exposure industrial category for on-highway diesel vehicles — long-haul trucks, distribution vehicles, delivery vans, bus fleets — where EGR soot contamination in Euro VI lube circuits, fuel quality variation across fleet fuelling networks, and fleet-scale procurement standardisation across multiple OEM brands create the primary filtration engineering and economic challenges.\",\"url\":\"https://elimfilters.com/knowledge-system/industries/trucks-fleets\",\"version\":\"1.0\"},{\"@type\":\"Dataset\",\"name\":\"Waste & Municipal\",\"description\":\"Waste & Municipal is a HIGH contamination exposure industrial category for diesel refuse collection, street sweeping, and municipal utility equipment, characterised by stop-start duty cycles generating 2–3× baseline lube oil soot loading, operator cab exposure to biological aerosols and urban PM2.5, and >90% fleet availability requirements that make contamination-related unplanned maintenance a direct service delivery failure.\",\"url\":\"https://elimfilters.com/knowledge-system/industries/waste-municipal\",\"version\":\"1.0\"},{\"@type\":\"Dataset\",\"name\":\"Air Filter\",\"description\":\"Air Filtration product system providing multi-layer particulate interception for diesel engine air intake paths, using MACROCORE™ Progressive Density Gradient elements achieving 99.9%–99.98% efficiency under ISO 5011 certification.\",\"url\":\"https://elimfilters.com/systems/airfilter\",\"version\":\"1.0\"},{\"@type\":\"Dataset\",\"name\":\"Water in Petroleum Products by Coulometric Karl Fischer Titration\",\"description\":\"ASTM D6304 is the standard test method for measuring water content in petroleum products using coulometric Karl Fischer titration, quantifying total water concentration in diesel fuel as mg/kg (ppm) by mass — providing the primary analytical tool for monitoring water contamination in fuel storage, delivery, and filtration systems against the EN 590 limit of 200 mg/kg.\",\"url\":\"https://elimfilters.com/knowledge-system/standards/astm-d6304\",\"version\":\"1.0\"},{\"@type\":\"Dataset\",\"name\":\"Road Vehicles — Cabin Air Filters — Requirements and Testing\",\"description\":\"DIN 71220 is the German DIN standard for road vehicle cabin air filter requirements and testing, specifying particle filtration efficiency (>80%), odour removal performance, and activated carbon layer testing for road vehicle passenger compartment filters — a predecessor to ISO 11155 that remains referenced in European OEM supplier specifications, particularly in German automotive supply chains.\",\"url\":\"https://elimfilters.com/knowledge-system/standards/din-71220\",\"version\":\"1.0\"},{\"@type\":\"Dataset\",\"name\":\"Road Vehicles — Air Filters for Passenger Compartments\",\"description\":\"ISO 11155 is the two-part international performance standard for road vehicle cabin air filters: ISO 11155-1 measures particle filtration efficiency (PM10, PM2.5) and airflow resistance; ISO 11155-2 measures activated carbon layer gaseous contaminant removal — together providing the measurement framework for classifying cabin filters by their capacity to protect operators from health-relevant particle and chemical contamination.\",\"url\":\"https://elimfilters.com/knowledge-system/standards/iso-11155\",\"version\":\"1.0\"},{\"@type\":\"Dataset\",\"name\":\"Petroleum Products — Determination of Water — Coulometric Karl Fischer Titration\",\"description\":\"ISO 12937 is the international coulometric Karl Fischer titration standard for measuring water content in petroleum products as mg/kg (ppm), functionally equivalent to ASTM D6304 and serving as the European and international market reference method for EN 590 diesel fuel water content compliance and ISO 8217 marine fuel water management.\",\"url\":\"https://elimfilters.com/knowledge-system/standards/iso-12937\",\"version\":\"1.0\"},{\"@type\":\"Dataset\",\"name\":\"Hydraulic Fluid Power — Filters — Multi-Pass Method for Evaluating Filtration Performance\",\"description\":\"ISO 16889 specifies the multi-pass test method for measuring filter element efficiency (Beta ratio) in hydraulic and lube oil systems, using ISO Medium Test Dust (ISO 12103-1 A3) to calculate particle capture efficiency across defined size classes (β₆, β₁₀, β₁₆, β₂₅).\",\"url\":\"https://elimfilters.com/knowledge-system/standards/iso-16889\",\"version\":\"1.0\"},{\"@type\":\"Dataset\",\"name\":\"Hydraulic Fluid Cleanliness Code\",\"description\":\"ISO 4406 is the international standard defining fluid cleanliness codes as three-number expressions (e.g., 16/14/11) representing particle count ranges at ≥4 µm(c), ≥6 µm(c), and ≥14 µm(c) per 100 mL of fluid, providing the universal measurement language for specifying and verifying hydraulic and lube oil contamination control targets.\",\"url\":\"https://elimfilters.com/knowledge-system/standards/iso-4406\",\"version\":\"1.0\"},{\"@type\":\"Dataset\",\"name\":\"Air Filter Performance Test\",\"description\":\"ISO 5011 is the standardised laboratory test method for measuring air intake filter efficiency (%), flow restriction (kPa), and dust-holding capacity (g) for internal combustion engine applications using ISO 12103-1 A2 fine test dust.\",\"url\":\"https://elimfilters.com/knowledge-system/standards/air-intake-systems\",\"version\":\"1.0\"},{\"@type\":\"Dataset\",\"name\":\"Fluid Power Systems — Hydraulic Filters — Method for Verifying Collapse/Burst Resistance\",\"description\":\"NFPA T2.14 is the fluid power standard specifying collapse and burst resistance test methods for hydraulic filter elements — verifying that filter element structure survives high differential pressures without structural failure that would release accumulated particle contamination and filter media fragments into the downstream hydraulic circuit.\",\"url\":\"https://elimfilters.com/knowledge-system/standards/nfpa-t214\",\"version\":\"1.0\"},{\"@type\":\"Dataset\",\"name\":\"Air Intake Cleanliness for Diesel Engines\",\"description\":\"SAE J1539 is the Society of Automotive Engineers classification standard defining air intake cleanliness requirements and test protocols for diesel engines, using SAE Fine Test Dust (ISO 12103-1 A2) to evaluate filtration performance in terms of dust ingestion limits and particle size distribution.\",\"url\":\"https://elimfilters.com/knowledge-system/standards/sae-j1539\",\"version\":\"1.0\"},{\"@type\":\"Dataset\",\"name\":\"Cabin Air Contamination\",\"description\":\"Cabin air contamination is the occupational exposure of equipment operators to respirable particulate matter (PM10, PM2.5, crystalline silica), chemical vapors (pesticides, exhaust gases), and biological particles (endotoxins, spores) entering the cab through degraded filtration, failed positive pressure, or contamination bypass pathways — creating regulatory OEL violation risk and long-term respiratory disease exposure.\",\"url\":\"https://elimfilters.com/knowledge-system/contamination/cabin-air-contamination\",\"version\":\"1.0\"},{\"@type\":\"Dataset\",\"name\":\"Diesel Water Contamination\",\"description\":\"Diesel water contamination is the presence of dissolved, free, or emulsified water in diesel fuel systems — entering through condensation, rain ingress, cross-contamination, or emulsification — that causes injector erosion at 1,600–2,500 bar operating pressures, microbiological growth at tank water interfaces, fuel filter plugging from biomass and ice crystal formation, and tank corrosion from microbial acid byproducts.\",\"url\":\"https://elimfilters.com/knowledge-system/contamination/diesel-water\",\"version\":\"1.0\"},{\"@type\":\"Dataset\",\"name\":\"Hydraulic System Contamination\",\"description\":\"Hydraulic system contamination is the presence of particles, water, and fluid degradation products in hydraulic fluid that causes proportional valve failure, pump wear, and system efficiency loss — operating through direct abrasive wear at 1–25 µm component clearances, water-accelerated fluid thermal degradation, and varnish deposition at valve bore surfaces causing control stiction.\",\"url\":\"https://elimfilters.com/knowledge-system/contamination/hydraulic-contamination\",\"version\":\"1.0\"},{\"@type\":\"Dataset\",\"name\":\"Particle Wear in Engines\",\"description\":\"Particle wear is the abrasive degradation of precision engine surfaces — piston rings, cylinder walls, crankshaft journals, and fuel injector components — caused by hard particles (silica, metal oxides, combustion debris) entrained in oil, fuel, and air intake circuits through two-body, three-body, and adhesive wear mechanisms.\",\"url\":\"https://elimfilters.com/knowledge-system/contamination/particle-wear\",\"version\":\"1.0\"},{\"@type\":\"Dataset\",\"name\":\"Engine Bearing Journal\",\"description\":\"The engine bearing journal is the precision crankshaft surface rotating within plain bearing shells at 15–50 µm hydrodynamic oil film clearance in diesel engines — a clearance range where particles above 10–15 µm in lube oil enter the bearing zone and initiate three-body abrasive wear between journal, particle, and bearing shell.\",\"url\":\"https://elimfilters.com/knowledge-system/components/engine-bearing-journal\",\"version\":\"1.0\"},{\"@type\":\"Dataset\",\"name\":\"Piston Ring Assembly\",\"description\":\"The piston ring assembly is the compression and oil sealing interface between piston rings and cylinder bore in diesel engines, operating at 5–15 µm ring-to-wall clearance — the tightest precision surface in a running engine — where hard abrasive particles above 5 µm act as micro-cutting tools during each of 2,000–5,000 piston strokes per minute.\",\"url\":\"https://elimfilters.com/knowledge-system/components/piston-ring-assembly\",\"version\":\"1.0\"},{\"@type\":\"Dataset\",\"name\":\"Turbocharger Bearing\",\"description\":\"Turbocharger bearing — floating-ring journal bearing with 10–25 µm clearance operating at 100,000–250,000 RPM — requires clean lube oil feed (ISO 4406 ≤ 19/17/14) and clean intake air (ISO 5011-certified filtration) to maintain the oil film thickness that prevents metal-to-metal contact and abrasive wear.\",\"url\":\"https://elimfilters.com (component reference — no dedicated page)\",\"version\":\"1.0\"},{\"@type\":\"Dataset\",\"name\":\"Dust Ingestion\",\"description\":\"Dust ingestion — engine contamination via the air intake path — is the leading cause of premature abrasive wear in off-highway diesel engines, occurring when ambient particulate bypasses or passes through the air filtration system and enters the combustion chamber.\",\"url\":\"https://elimfilters.com/knowledge-system/contamination/particle-wear\",\"version\":\"1.0\"},{\"@type\":\"Dataset\",\"name\":\"Engine Oil Contamination\",\"description\":\"Engine oil contamination — accumulation of abrasive particles in diesel engine lube oil circuits — is the most universal contamination failure mode across all engine-powered industrial equipment, measurable and preventable via ISO 4406 particle cleanliness code management.\",\"url\":\"https://elimfilters.com/knowledge-system/contamination/particle-wear\",\"version\":\"1.0\"},{\"@type\":\"Dataset\",\"name\":\"Fuel Filter Plugging\",\"description\":\"Fuel filter plugging — premature blockage of diesel fuel filters by water contamination, microbial growth, and associated debris — is the most frequent fuel system maintenance event in off-highway, marine, and stationary engine applications.\",\"url\":\"https://elimfilters.com/knowledge-system/contamination/diesel-water\",\"version\":\"1.0\"},{\"@type\":\"Dataset\",\"name\":\"Hydraulic Valve Failure\",\"description\":\"Hydraulic valve failure from contamination — particle and water-induced degradation of proportional valve spools and pump components — is the primary precision control failure mode in construction, mining, and industrial hydraulic systems.\",\"url\":\"https://elimfilters.com/knowledge-system/contamination/hydraulic-contamination\",\"version\":\"1.0\"},{\"@type\":\"Dataset\",\"name\":\"Operator Dust Exposure\",\"description\":\"Operator dust exposure — ingress of respirable particulate and chemical contaminants into equipment operator cabs — is the primary occupational health contamination problem in construction, mining, and agricultural equipment, governed by ISO 11155 cab air standards and occupational health regulations.\",\"url\":\"https://elimfilters.com/knowledge-system/standards/cabin-safety-systems\",\"version\":\"1.0\"},{\"@type\":\"Dataset\",\"name\":\"Primary Intake Protection\",\"description\":\"Primary Intake Protection — the MACROCORE™-technology filter element family for primary-duty air intake applications in heavy-duty diesel engines, covering approximately 120 SKUs across mining, agricultural, construction, and commercial transport configurations, all ISO 5011 certified to 99.9%–99.98% efficiency.\",\"url\":\"https://elimfilters.com/systems/airfilter\",\"version\":\"1.0\"},{\"@type\":\"Dataset\",\"name\":\"Primary Cabin Air Protection\",\"description\":\"Primary Cabin Air Protection — the MICROKAPPA™-technology cabin air filter element family for operator health protection in heavy-duty equipment cabs, covering approximately 65 SKUs across agricultural, construction, mining, bus/coach, railway, and waste management applications, ISO 11155-1 certified to >95% PM10 and >85% PM2.5 efficiency.\",\"url\":\"https://elimfilters.com/systems/cabin-primary\",\"version\":\"1.0\"},{\"@type\":\"Dataset\",\"name\":\"Primary Fuel Protection\",\"description\":\"Primary Fuel Protection — the HYDROCORE™-technology filter element family for diesel fuel water separation and particle filtration, covering approximately 85 SKUs across agricultural, marine, mining, power generation, and commercial transport applications, meeting ASTM D6304 and ISO 12937 water content standards.\",\"url\":\"https://elimfilters.com/systems/fuel-primary\",\"version\":\"1.0\"},{\"@type\":\"Dataset\",\"name\":\"Primary Hydraulic Protection\",\"description\":\"Primary Hydraulic Protection — the NANOFORCE™-technology filter element family for precision particle control in hydraulic systems, covering approximately 95 SKUs rated Beta(x[c]) ≥ 1000 at 5 µm per ISO 16889, targeting ISO 4406 16/14/11 cleanliness across agriculture, construction, mining, oil/gas, and power generation applications.\",\"url\":\"https://elimfilters.com/systems/hydraulic-primary\",\"version\":\"1.0\"},{\"@type\":\"Dataset\",\"name\":\"Primary Lube Oil Protection\",\"description\":\"Primary Lube Oil Protection — the SYNTRAX™-technology lube oil filter element family for full-flow engine and transmission oil filtration, covering approximately 110 SKUs targeting ISO 4406 16/14/11 cleanliness across all major diesel engine families in mining, agriculture, construction, transport, marine, and power generation applications.\",\"url\":\"https://elimfilters.com/systems/lube-primary\",\"version\":\"1.0\"}]}";

