export const JSONLD_STANDARDS_INDEX = "{\"@context\":\"https://schema.org\",\"@type\":\"CollectionPage\",\"name\":\"Industrial Filtration Standards — ELIMFILTERS Knowledge System\",\"description\":\"Index of international standards governing industrial filtration: ISO 16889, ISO 4406, ISO 5011, ISO 11155, ISO 12937, ASTM D6304, SAE J1539, DIN 71220, NFPA T2.14.\",\"url\":\"https://elimfilters.com/knowledge-system/standards\",\"publisher\":{\"@type\":\"Organization\",\"name\":\"ELIMFILTERS\",\"url\":\"https://elimfilters.com\"},\"hasPart\":[{\"@type\":\"DefinedTerm\",\"name\":\"Water in Petroleum Products by Coulometric Karl Fischer Titration\",\"identifier\":\"ASTM_D6304\",\"description\":\"ASTM D6304 is the standard test method for measuring water content in petroleum products using coulometric Karl Fischer titration, quantifying total water concentration in diesel fuel as mg/kg (ppm) by mass — providing the primary analytical tool for monitoring water contamination in fuel storage, delivery, and filtration systems against the EN 590 limit of 200 mg/kg.\",\"url\":\"https://elimfilters.com/knowledge-system/standards/astm-d6304\",\"inDefinedTermSet\":\"https://elimfilters.com/knowledge-system\"},{\"@type\":\"DefinedTerm\",\"name\":\"Road Vehicles — Cabin Air Filters — Requirements and Testing\",\"identifier\":\"DIN_71220\",\"description\":\"DIN 71220 is the German DIN standard for road vehicle cabin air filter requirements and testing, specifying particle filtration efficiency (>80%), odour removal performance, and activated carbon layer testing for road vehicle passenger compartment filters — a predecessor to ISO 11155 that remains referenced in European OEM supplier specifications, particularly in German automotive supply chains.\",\"url\":\"https://elimfilters.com/knowledge-system/standards/din-71220\",\"inDefinedTermSet\":\"https://elimfilters.com/knowledge-system\"},{\"@type\":\"DefinedTerm\",\"name\":\"Road Vehicles — Air Filters for Passenger Compartments\",\"identifier\":\"ISO_11155\",\"description\":\"ISO 11155 is the two-part international performance standard for road vehicle cabin air filters: ISO 11155-1 measures particle filtration efficiency (PM10, PM2.5) and airflow resistance; ISO 11155-2 measures activated carbon layer gaseous contaminant removal — together providing the measurement framework for classifying cabin filters by their capacity to protect operators from health-relevant particle and chemical contamination.\",\"url\":\"https://elimfilters.com/knowledge-system/standards/iso-11155\",\"inDefinedTermSet\":\"https://elimfilters.com/knowledge-system\"},{\"@type\":\"DefinedTerm\",\"name\":\"Petroleum Products — Determination of Water — Coulometric Karl Fischer Titration\",\"identifier\":\"ISO_12937\",\"description\":\"ISO 12937 is the international coulometric Karl Fischer titration standard for measuring water content in petroleum products as mg/kg (ppm), functionally equivalent to ASTM D6304 and serving as the European and international market reference method for EN 590 diesel fuel water content compliance and ISO 8217 marine fuel water management.\",\"url\":\"https://elimfilters.com/knowledge-system/standards/iso-12937\",\"inDefinedTermSet\":\"https://elimfilters.com/knowledge-system\"},{\"@type\":\"DefinedTerm\",\"name\":\"Hydraulic Fluid Power — Filters — Multi-Pass Method for Evaluating Filtration Performance\",\"identifier\":\"ISO_16889\",\"description\":\"ISO 16889 specifies the multi-pass test method for measuring filter element efficiency (Beta ratio) in hydraulic and lube oil systems, using ISO Medium Test Dust (ISO 12103-1 A3) to calculate particle capture efficiency across defined size classes (β₆, β₁₀, β₁₆, β₂₅).\",\"url\":\"https://elimfilters.com/knowledge-system/standards/iso-16889\",\"inDefinedTermSet\":\"https://elimfilters.com/knowledge-system\"},{\"@type\":\"DefinedTerm\",\"name\":\"Hydraulic Fluid Cleanliness Code\",\"identifier\":\"ISO_4406\",\"description\":\"ISO 4406 is the international standard defining fluid cleanliness codes as three-number expressions (e.g., 16/14/11) representing particle count ranges at ≥4 µm(c), ≥6 µm(c), and ≥14 µm(c) per 100 mL of fluid, providing the universal measurement language for specifying and verifying hydraulic and lube oil contamination control targets.\",\"url\":\"https://elimfilters.com/knowledge-system/standards/iso-4406\",\"inDefinedTermSet\":\"https://elimfilters.com/knowledge-system\"},{\"@type\":\"DefinedTerm\",\"name\":\"Air Filter Performance Test\",\"identifier\":\"ISO_5011\",\"description\":\"ISO 5011 is the standardised laboratory test method for measuring air intake filter efficiency (%), flow restriction (kPa), and dust-holding capacity (g) for internal combustion engine applications using ISO 12103-1 A2 fine test dust.\",\"url\":\"https://elimfilters.com/knowledge-system/standards/air-intake-systems\",\"inDefinedTermSet\":\"https://elimfilters.com/knowledge-system\"},{\"@type\":\"DefinedTerm\",\"name\":\"Fluid Power Systems — Hydraulic Filters — Method for Verifying Collapse/Burst Resistance\",\"identifier\":\"NFPA_T214\",\"description\":\"NFPA T2.14 is the fluid power standard specifying collapse and burst resistance test methods for hydraulic filter elements — verifying that filter element structure survives high differential pressures without structural failure that would release accumulated particle contamination and filter media fragments into the downstream hydraulic circuit.\",\"url\":\"https://elimfilters.com/knowledge-system/standards/nfpa-t214\",\"inDefinedTermSet\":\"https://elimfilters.com/knowledge-system\"},{\"@type\":\"DefinedTerm\",\"name\":\"Air Intake Cleanliness for Diesel Engines\",\"identifier\":\"SAE_J1539\",\"description\":\"SAE J1539 is the Society of Automotive Engineers classification standard defining air intake cleanliness requirements and test protocols for diesel engines, using SAE Fine Test Dust (ISO 12103-1 A2) to evaluate filtration performance in terms of dust ingestion limits and particle size distribution.\",\"url\":\"https://elimfilters.com/knowledge-system/standards/sae-j1539\",\"inDefinedTermSet\":\"https://elimfilters.com/knowledge-system\"}]}";

