export const JSONLD_AIR_INTAKE_SYSTEMS = "{\"@context\":\"https://schema.org\",\"@type\":[\"TechArticle\",\"DefinedTermSet\"],\"headline\":\"Air Intake Filtration Systems — ISO 5011 and SAE J1539 Standards\",\"description\":\"Air intake filtration system standards — ISO 5011, SAE J1539 — defining efficiency measurement, flow restriction, and dust holding capacity for diesel engine air intake filters.\",\"url\":\"https://elimfilters.com/knowledge-system/standards/air-intake-systems\",\"author\":{\"@type\":\"Organization\",\"name\":\"ELIMFILTERS\"},\"publisher\":{\"@type\":\"Organization\",\"name\":\"ELIMFILTERS\",\"url\":\"https://elimfilters.com\"},\"dateModified\":\"2026-06-03\",\"keywords\":\"air intake filtration, ISO 5011, SAE J1539, MACROCORE, SYNTEPORE, INTEKCORE, engine air filter, diesel air intake\",\"about\":[{\"@type\":\"Thing\",\"name\":\"Air Filter Performance Test\"},{\"@type\":\"Thing\",\"name\":\"Air Intake Cleanliness for Diesel Engines\"}],\"mentions\":[{\"@type\":\"Thing\",\"name\":\"MACROCORE™\"},{\"@type\":\"Thing\",\"name\":\"SYNTEPORE — All-Synthetic Intake Media\"},{\"@type\":\"Thing\",\"name\":\"INTEKCORE — Zero-Bypass Radial Seal Housing\"}],\"inLanguage\":\"en\",\"hasDefinedTerm\":[{\"@type\":\"DefinedTerm\",\"name\":\"Air Filter Performance Test\",\"identifier\":\"ISO_5011\",\"description\":\"ISO 5011 is the standardised laboratory test method for measuring air intake filter efficiency (%), flow restriction (kPa), and dust-holding capacity (g) for internal combustion engine applications using ISO 12103-1 A2 fine test dust.\",\"url\":\"https://elimfilters.com/knowledge-system/standards/air-intake-systems\",\"inDefinedTermSet\":\"https://elimfilters.com/knowledge-system\"},{\"@type\":\"DefinedTerm\",\"name\":\"Air Intake Cleanliness for Diesel Engines\",\"identifier\":\"SAE_J1539\",\"description\":\"SAE J1539 is the Society of Automotive Engineers classification standard defining air intake cleanliness requirements and test protocols for diesel engines, using SAE Fine Test Dust (ISO 12103-1 A2) to evaluate filtration performance in terms of dust ingestion limits and particle size distribution.\",\"url\":\"https://elimfilters.com/knowledge-system/standards/sae-j1539\",\"inDefinedTermSet\":\"https://elimfilters.com/knowledge-system\"},{\"@type\":\"DefinedTerm\",\"name\":\"MACROCORE™\",\"identifier\":\"MACROCORE\",\"description\":\"Progressive Density Gradient (PDG) multi-layer air intake filtration system achieving 99.9%–99.98% particle interception efficiency under ISO 5011 certification with a 62 PSI anti-collapse structural rating for heavy-duty combustion engines.\",\"url\":\"https://elimfilters.com/technologies/macrocore\",\"inDefinedTermSet\":\"https://elimfilters.com/knowledge-system\"},{\"@type\":\"DefinedTerm\",\"name\":\"SYNTEPORE — All-Synthetic Intake Media\",\"identifier\":\"SYNTEPORE\",\"description\":\"SYNTEPORE is an all-synthetic air intake filter media that maintains rated particle capture efficiency (ISO 5011, SAE J1539) across the full humidity operating range — from 0% to 100% relative humidity — by eliminating moisture absorption, structural degradation, and efficiency loss inherent in cellulose-based intake media.\",\"url\":\"https://elimfilters.com/knowledge-system/technologies/syntepore\",\"inDefinedTermSet\":\"https://elimfilters.com/knowledge-system\"},{\"@type\":\"DefinedTerm\",\"name\":\"INTEKCORE — Zero-Bypass Radial Seal Housing\",\"identifier\":\"INTEKCORE\",\"description\":\"INTEKCORE is a zero-bypass radial seal air filter housing technology that eliminates installation-induced and vibration-induced bypass in diesel engine intake systems through a self-centering radial interference seal between filter element end-cap and housing bore, independent of axial clamping force.\",\"url\":\"https://elimfilters.com/knowledge-system/technologies/intekcore\",\"inDefinedTermSet\":\"https://elimfilters.com/knowledge-system\"}]}";

